fn looks_like_missing_bracket(text: &str) -> bool {
    let opens: usize = text.chars().filter(|&c| c == '(' || c == '[' || c == '{').count();
    let closes: usize = text.chars().filter(|&c| c == ')' || c == ']' || c == '}').count();
